mod audio;mod game;mod video;
use game::Game;
include!("cinematic_export_helpers.rs");
fn started()->Game{let mut g=Game::new(false).unwrap();for f in 0..900{g.update([if f==120{8}else{0},0]).unwrap();}g}
fn main(){let root=std::env::args().nth(1).expect("output project root");std::fs::create_dir_all(format!("{root}/assets/cinematics")).unwrap();
 for stage in 0..5{let mut g=started();g.memory[0x30]=stage;g.memory[0x18]=5;g.memory[0x2c]=1;g.memory[0x34]=1;for _ in 0..90{g.update([0;2]).unwrap();}for _ in 0..5000{g.memory[0x52]=255;g.memory[0x53]=255;g.memory[0x3c]=1;g.update([3,0]).unwrap();if g.memory[0x43]>=11&&g.memory[0x3a]!=0&&g.memory[0x3b]!=0{break;}}for _ in 0..600{g.memory[0x52]=255;g.memory[0x53]=255;g.update([3,0]).unwrap();}g.memory[0x3b]=0;g.memory[0x42]=0xfe;drain_sounds();let mut cap=Capture::new();for frame in 0..2000{g.update([0;2]).unwrap();if g.memory[0x18]!=7{break;}if stage==0 && frame==250{g.video.export_digits(&format!("{root}/assets/cinematics/score_digits.png"));}cap.sound_commands(drain_sounds());cap.frame(g.video.render());}cap.save(&root,&format!("stage_clear_{:02}",stage+1),0);let mut load=Capture::new();for load_frame in 0..256{load.sound_commands(drain_sounds());load.frame(g.video.render());g.update([0;2]).unwrap();if load_frame > 0 && g.memory[0x18]==5 && g.memory[0x2c]==3{break;}}load.save(&root,&format!("stage_load_{:02}",stage+2),0);}
 for stage in 0..6{let mut g=started();g.memory[0x30]=stage;g.memory[0x31]=0;g.memory[0x32]=0;for _ in 0..120{g.update([0;2]).unwrap();}drain_sounds();g.update([8,0]).unwrap();let mut load=Capture::new();for load_frame in 0..256{load.sound_commands(drain_sounds());load.frame(g.video.render());g.update([0;2]).unwrap();if load_frame > 0 && g.memory[0x18]==5 && g.memory[0x2c]==3{break;}}load.save(&root,&format!("continue_load_{:02}",stage+1),0);}
 for (name,select) in [("continue_yes",false),("continue_no",true)]{let mut g=started();g.memory[0x31]=0;g.memory[0x32]=0;for _ in 0..120{g.update([0;2]).unwrap();}if select{g.update([4,0]).unwrap();}for _ in 0..4{g.update([0;2]).unwrap();}drain_sounds();let mut cap=Capture::new();cap.sound_commands(drain_sounds());cap.frame(g.video.render());cap.save(&root,name,0);}
 let mut g=started();g.memory[0x34]=3;g.memory[0x31]=0;g.memory[0x32]=0;drain_sounds();let mut cap=Capture::new();for _ in 0..1000{g.update([0;2]).unwrap();if g.memory[0x18]!=6{break;}cap.sound_commands(drain_sounds());cap.frame(g.video.render());}cap.save(&root,"game_over",0);
}
